// DefaultTuning.swift — tuned default values of the fusion / arbiter tunables.
//
// This file is (re)generated by `gazefuse-bench tune --write-defaults`; edit the
// ranges in FusionTuning.swift rather than the numbers here. The config structs'
// initializers use these constants as their default arguments, so the tuned values
// are what the app gets with `EKFCursorFusionConfig()` / `ClickArbiterConfig()`.
import Foundation

public enum FusionDefaultTuning {
    // EKFCursorFusionConfig
    public static let gazeSigmaPoints: Double = 30
    public static let positionProcessSigma: Double = 4
    public static let biasProcessSigma: Double = 2
    public static let biasPriorSigma: Double = 60
    public static let biasCorrelationLength: Double = 500
    public static let saccadeGateNIS: Double = 9.21
    public static let saccadeWindowGateNIS: Double = 20
    public static let saccadeMinJumpPoints: Double = 40
    public static let saccadeConfirmSamples: Int = 2
    public static let saccadeClusterSigmas: Double = 3
    public static let headAccelerationSigma: Double = 5000
    // HeadPointerConfig
    public static let headDeadbandRadPerSec: Double = 0.02
    public static let headPointsPerRadian: Double = 1500
    public static let headAccelExponent: Double = 0.5
    public static let headVelocitySigma: Double = 10
    // ClickArbiterConfig
    public static let onsetLookback: Double = 0.1
    // DirectGazeCursorConfig
    public static let directMinCutoff: Double = 1.0
    public static let directBeta: Double = 0.01
}
